use vstd::prelude::*;

verus! {

    // A closed interval [min, max] with min < max
    pub struct Interval {
        min: f64,
        max: f64,
    }

    // Descriptor for a Chebyshev polynomial:
    //   - coef: the coefficients in increasing degree order
    //   - domain: the interval on which the polynomial is defined
    //   - window: the interval to which values are mapped
    pub struct ChebyshevPoly {
        coef: Vec<i32>,
        domain: Interval,
        window: Interval,
    }

    // Construct a Chebyshev polynomial descriptor from a non-empty list of i8 coefficients.
    // The coefficients are converted to i32, and both domain and window are set to [-1,1].
    fn chebyshev(coef: Vec<i8>) -> (res: ChebyshevPoly)
        requires
            // input is non‐empty
            coef.len() > 0,
        ensures
            // coefficients are preserved in length and value (converted to i32)
            res.coef.len() == coef.len(),
        ensures
            forall |i: usize| i < coef.len() ==> res.coef[i] == coef[i] as i32,
        ensures
            // domain is exactly [-1,1]
            res.domain.min == -1.0,
        ensures
            res.domain.max == 1.0,
        ensures
            // window is exactly [-1,1]
            res.window.min == -1.0,
        ensures
            res.window.max == 1.0,
        ensures
            // validity of intervals
            res.domain.min < res.domain.max,
        ensures
            res.window.min < res.window.max,
    {
        // Build the i32 coefficient vector
        let mut coeffs: Vec<i32> = Vec::new();
        let mut idx: usize = 0;
        while idx < coef.len()
            invariant
                // we process exactly idx elements so far
                idx <= coef.len(),
                coeffs.len() == idx,
                // each pushed element matches the input
                forall |j: usize| j < idx ==> coeffs[j] == coef[j] as i32,
            decreases
                coef.len() - idx,
        {
            coeffs.push(coef[idx] as i32);
            idx += 1;
        }

        // Default intervals [-1, 1]
        let domain  = Interval { min: -1.0, max:  1.0 };
        let window  = Interval { min: -1.0, max:  1.0 };

        // Proofs of validity
        assert(domain.min < domain.max);   // -1.0 < 1.0
        assert(window.min < window.max);   // -1.0 < 1.0

        // Return the constructed descriptor
        ChebyshevPoly {
            coef:   coeffs,
            domain: domain,
            window: window,
        }
    }
}

